-- Temporary user-validation mode. Apply only after the SIGAP schema is installed.
-- New non-anonymous Auth users receive an isolated practice workspace atomically.
-- Disable after testing: update sigap_private.test_registration_settings set enabled=false;
create table if not exists sigap_private.test_registration_settings (
 id boolean primary key default true check(id),
 organization_id uuid not null references public.sigap_organizations(id),
 enabled boolean not null default false
);
alter table sigap_private.test_registration_settings enable row level security;
revoke all on sigap_private.test_registration_settings from public, anon, authenticated;

do $$
declare org uuid;
begin
 if (select count(distinct organization_id) from public.sigap_memberships where role='admin' and status='active') <> 1 then
  raise exception 'TEST_REGISTRATION_REQUIRES_ONE_ADMIN_ORGANIZATION';
 end if;
 select organization_id into org from public.sigap_memberships where role='admin' and status='active' limit 1;
 insert into sigap_private.test_registration_settings(id,organization_id,enabled) values(true,org,true)
 on conflict(id) do update set organization_id=excluded.organization_id,enabled=true;
end $$;

create or replace function sigap_private.provision_test_registration() returns trigger
